// 一项失败只改自己的状态，不撤销已经完成或仍在排队的其他项。
function queueAfterItemFailure(items, failedId) {
    return (Array.isArray(items) ? items : []).map(item => item?.id === failedId ? { ...item, status: 'failed' } : { ...item });
}

