            if (!isProjectRemote(result?.remoteUrl) || !/^[a-f0-9]{7,40}$/i.test(result?.shortCommitHash || '')) throw updateError('更新结果尚未确认，请稍后检查版本。');
            return { message: result.isUpToDate ? '已强制检查：仓库中没有新更新。' : '已拉取更新。请在保存聊天后手动刷新页面。' };
