        runtimeState.activeArchiveReadOnly = true;
        if (readOnly === false) globalThis.toastr?.info?.(runtimeState.activeArchiveSnapshot.taskResultDraftId ? '当前是独立保存的成果；请返回当前档案继续操作。' : '旧版本永久只读；请返回当前档案继续操作。', '心迹回廊');
