        const sourceType = item?.sourceType === CALENDAR_NOTE_SOURCE.SETTING ? CALENDAR_NOTE_SOURCE.SETTING : CALENDAR_NOTE_SOURCE.ARCHIVE;
        const title = kind === CALENDAR_NOTE_KIND.SPECIAL ? '特别备注' : '便签';
