const endingNeedsScenes = __m_modes_endingData_js.endingNeedsScenes;
const endingOutlinePrompt = __m_modes_endingData_js.endingOutlinePrompt;
const endingRouteDetailPrompt = __m_modes_endingData_js.endingRouteDetailPrompt;
const endingRouteEvidenceKey = __m_modes_endingData_js.endingRouteEvidenceKey;
const mergeEndingConfessions = __m_modes_endingData_js.mergeEndingConfessions;
const normalizeEndingConfessionLines = __m_modes_endingData_js.normalizeEndingConfessionLines;
const normalizeEndingConfessionReplays = __m_modes_endingData_js.normalizeEndingConfessionReplays;
